import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"甲族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/甲族.md","filePath":"表层/种族/甲族.md","lastUpdated":null}'),e={name:"表层/种族/甲族.md"};function i(n,a,s,h,u,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="甲族" tabindex="-1">甲族 <a class="header-anchor" href="#甲族" aria-label="Permalink to &quot;甲族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>甲族是五大主族之一，共同体时期承担军事相关的一切，以<strong>服从与执行力</strong>为种族核心特质。共同体时期旧时代国防军几乎全由甲族组成。经历数次重大灾变后，甲族已<strong>近乎灭绝</strong>：灭绝原因无人记载（相关记录被刻意抹除），幸存者以个计数，其中一位长期做客于红星孤儿院。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：<strong>非毛系</strong>种族，身体覆盖坚硬的外骨骼/甲壳结构，与其余主族的外貌差异极大。</li><li><strong>外观</strong>：与大陆主流的毛系福瑞审美差异显著，过去一度被外界视为&quot;畸形怪种&quot;。由于其近乎灭绝且长期消失在公众视野之中，这些负面评价也逐渐无人在意。</li><li><strong>繁衍与习性</strong>：繁衍方式与生活习性与其他种族差异极大。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-服从与执行力" tabindex="-1">核心特质：服从与执行力 <a class="header-anchor" href="#核心特质-服从与执行力" aria-label="Permalink to &quot;核心特质：服从与执行力&quot;">​</a></h3><ul><li><strong>绝对服从</strong>：天生具备对上级命令的高度服从性。</li><li><strong>执行力</strong>：任务完成能力极强，是五大主族中执行效率最高的种族。</li><li><strong>纪律性</strong>：个体间配合默契，高度纪律化。</li><li><strong>使命必达</strong>：将完成任务视为最高使命。</li></ul><h3 id="弱点" tabindex="-1">弱点 <a class="header-anchor" href="#弱点" aria-label="Permalink to &quot;弱点&quot;">​</a></h3><ul><li><strong>缺乏反击经验</strong>：习惯于接受指令，缺乏独立行动和反击的经验，面对需要独立判断的复杂局势时显得无力。</li><li><strong>不擅长政治博弈</strong>：不擅长舆论、社会斗争等领域。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体时期-军事担当" tabindex="-1">共同体时期：军事担当 <a class="header-anchor" href="#共同体时期-军事担当" aria-label="Permalink to &quot;共同体时期：军事担当&quot;">​</a></h3><p>在五大主族分工的共同体体系中，甲族承担<strong>军事相关的一切</strong>：</p><ul><li>负责共同体的国防事务与军事行动。</li><li><strong>旧时代国防军几乎全由甲族组成</strong>。</li><li>在共同体五星旗帜上，甲族占据一角，代表军事与防御的力量。</li></ul><h3 id="近乎灭绝" tabindex="-1">近乎灭绝 <a class="header-anchor" href="#近乎灭绝" aria-label="Permalink to &quot;近乎灭绝&quot;">​</a></h3><p>共同体崩溃后，甲族遭受重大灾变，<strong>近乎灭绝</strong>。其灭绝原因<strong>无人记载</strong>——相关记录被刻意抹除，成为历史中的一处空白。幸存者以个计数，遁入山林，长期消失于世人视野。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>甲族目前近乎灭绝，作为种族已退出大陆政治舞台。</p><ul><li><strong>幸存者</strong>：幸存者以个计数，分散隐藏，彼此联系稀少。</li><li><strong>红星孤儿院</strong>：有一位甲族在红星孤儿院内<strong>长期做客</strong>。</li><li><strong>外界认知</strong>：其繁衍与生活习性与其他种族差异极大，过去一度被外界视为&quot;畸形怪种&quot;；由于其几乎灭绝，长期消失在公众视野之中，这些负面评价也逐渐无人在意。</li></ul><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>甲族灭绝的具体经过与幸存者的经历不属表层认知。</p></blockquote><ul><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./鹰族">鹰族</a></li></ul><hr>',31)])])}const q=r(e,[["render",i]]);export{g as __pageData,q as default};
